{
  "type": "object",
  "required": ["score", "tier", "reason", "suggested_next_action"],
  "properties": {
    "score": {
      "type": "integer",
      "minimum": 1,
      "maximum": 10,
      "description": "How good this lead is, using the criteria's bands"
    },
    "tier": {
      "type": "string",
      "enum": ["hot", "warm", "cold"],
      "description": "Must match the score using the thresholds in the criteria"
    },
    "reason": {
      "type": "string",
      "description": "One sentence quoting real details from this lead"
    },
    "suggested_next_action": {
      "type": "string",
      "description": "One short instruction for whoever picks the lead up"
    }
  }
}

