// Never trust the model's own arithmetic.
//
// The parser guarantees the SHAPE. This guarantees the MEANING: the tier is
// recalculated from the score, so a model that says "score 9, tier cold"
// cannot send a hot lead quietly into the cold pile.
//
// If anything is unusable, the lead still continues - marked "unscored" - so
// a scoring problem never costs the business a lead.

const HOT = 8;   // thresholds live in the criteria document; these mirror it
const WARM = 5;

function tierFor(score) {
  if (score >= HOT) return 'hot';
  if (score >= WARM) return 'warm';
  return 'cold';
}

const leads = $('Turn the Doc into text').all();

return $input.all().map((item, index) => {
  const carried = leads[index]?.json || leads[0]?.json || {};
  const output = item.json?.output || item.json || {};

  const raw = Number(output.score);
  const usable = Number.isFinite(raw) && raw >= 1 && raw <= 10 && String(output.reason || '').trim().length > 0;

  const score = usable ? Math.round(raw) : null;
  const tier = usable ? tierFor(score) : 'unscored';

  return {
    json: {
      ...carried,
      scoring: {
        score,
        tier,
        reason: usable ? String(output.reason).trim() : 'The scoring step did not return a usable answer.',
        suggested_next_action: usable
          ? String(output.suggested_next_action || 'Review this lead by hand.').trim()
          : 'Review this lead by hand.',
        // Recorded when the model disagreed with itself, so the owner can see
        // how often that happens rather than guessing.
        model_said_tier: String(output.tier || ''),
        corrected: usable && String(output.tier || '') !== tier,
        scored_ok: usable,
      },
    },
  };
});

// Did HubSpot already know this email?
//
// A returning lead is a buying signal, not noise: someone who asked twice is
// more interested than someone who asked once. It is flagged here so the alert
// can say so, rather than being silently merged.

const scored = $('Check the score').all();
const found = $input.all();

return scored.map((item, index) => {
  const hit = found[index]?.json || found[0]?.json || {};
  // The search node emits an empty item when nothing matched (alwaysOutputData),
  // so "has an id" is the test, not "has an item".
  const existingId = hit.id || hit.contactId || null;

  return {
    json: {
      ...item.json,
      crm: {
        returning: Boolean(existingId),
        existing_contact_id: existingId,
      },
    },
  };
});

// One row per lead, with keys named exactly like the Lead Log headers so the
// Sheets node can map them by name. Doing it here rather than in the Sheets
// node keeps the column list readable and diffable.

return $('Is this a returning lead?').all().map((item) => {
  const { lead, scoring, crm } = item.json;
  return {
    json: {
      received_at: lead.received_at,
      lead_id: lead.lead_id,
      source: lead.source,
      source_detail: lead.source_detail,
      first_name: lead.first_name,
      last_name: lead.last_name,
      email: lead.email,
      phone: lead.phone,
      company: lead.company,
      city: lead.city,
      // Numbers are written as numbers: the weekly summary adds them up.
      office_size_sqft: lead.office_size_sqft ?? '',
      tier: scoring.tier + (crm?.returning ? ' (returning)' : ''),
      score: scoring.score ?? '',
      reason: scoring.reason,
    },
  };
});

